// 02-85_propose-checked.cjs - generated by zemory hook guard (plan/27). Settings: policy.json.
"use strict";
const fs = require("node:fs");
const path = require("node:path");

const BT = String.fromCharCode(96);
const relOf = (root, abs) => path.relative(root, path.resolve(root, abs)).replace(/\\/g, "/");
const inside = (rel) => rel && !rel.startsWith("..") && !path.isAbsolute(rel);

// What the call ADDS and REMOVES for a file tool; newLines = added lines not already present (multiset, trimmed).
function edit(payload, root) {
  const tool = payload.tool_name || "";
  const ti = payload.tool_input || {};
  const abs = ti.file_path || ti.notebook_path || "";
  if (!abs || !["Write", "Edit", "MultiEdit", "NotebookEdit"].includes(tool)) return null;
  const rel = relOf(root, abs);
  if (!inside(rel)) return null;
  let added = "", removed = "", exists = false;
  try { exists = fs.existsSync(abs); } catch { exists = false; }
  if (tool === "Write") {
    added = String(ti.content || "");
    try { removed = exists ? fs.readFileSync(abs, "utf8") : ""; } catch { removed = ""; }
  } else if (tool === "Edit") {
    added = String(ti.new_string || ""); removed = String(ti.old_string || "");
  } else if (tool === "MultiEdit") {
    for (const e of ti.edits || []) { added += "\n" + (e.new_string || ""); removed += "\n" + (e.old_string || ""); }
  } else {
    added = String(ti.new_source || "");
  }
  const seen = new Map();
  for (const l of removed.split(/\r?\n/)) { const k = l.trim(); if (k) seen.set(k, (seen.get(k) || 0) + 1); }
  const newLines = [];
  for (const l of added.split(/\r?\n/)) {
    const k = l.trim();
    if (!k) continue;
    const n = seen.get(k) || 0;
    if (n > 0) seen.set(k, n - 1); else newLines.push(l);
  }
  return { tool, abs, rel, added, removed, exists, newLines };
}

// The rule's own text, capped. Folder harness (plan/28 §0d): the body of the rule's header file beside this hook. File harness: the line
// carrying its number in the rules file plus its continuation lines.
function ownRule(root) {
  try {
    // the header file is named after the rule folder (plan/28 §0p); an older copy still has RULE.md
    const own = path.join(__dirname, path.basename(__dirname) + ".md");
    const file = fs.existsSync(own) ? own : path.join(__dirname, "RULE.md");
    let lines = fs.readFileSync(file, "utf8").split(/\r?\n/);
    if (lines[0] === "---") lines = lines.slice(lines.indexOf("---", 1) + 1);
    // a bilingual law (plan/29 §11): English first, the Vietnamese half under "## Luật là gì" - the block quotes the English
    const vi = lines.findIndex((l) => /^##\s+Luật là gì\s*$/.test(l));
    if (vi > 0) lines = lines.slice(0, vi);
    const body = lines.filter((l, i) => i > 0 || l.trim()).slice(0, 30).map((l) => (l.length > 400 ? l.slice(0, 400) + "…" : l));
    return { rel: path.relative(root, file).replace(/\\/g, "/"), text: body.join("\n").trim() };
  } catch {
    return null;
  }
}
function ruleText(root, file, id) {
  try {
    const lines = fs.readFileSync(path.join(root, file), "utf8").split(/\r?\n/);
    const at = lines.findIndex((l) => l.includes(BT + id + BT) || l.startsWith(id + " "));
    if (at < 0) return "";
    const out = [lines[at]];
    for (let i = at + 1; i < lines.length && out.length < 12; i++) {
      const l = lines[i];
      if (!l.trim() || /^(- |#|\x60\x60\x60|\d{2}-\d+ |<!--)/.test(l)) break;
      out.push(l);
    }
    return out.map((l) => (l.length > 400 ? l.slice(0, 400) + "…" : l)).join("\n");
  } catch {
    return "";
  }
}
// The citation: a hook inside a renamed rule folder (plan/28 §0o) cites the folder's full name, which is always the rule's
// current name; a legacy folder or the file harness keeps "rule <id>".
function citation(id) {
  const folder = path.basename(__dirname);
  return /^(Rule|Cons)_(Gate|Keys|Core)_\d+_/.test(folder) ? folder : "rule " + id;
}
function blocked(root, policy, id, what) {
  const own = ownRule(root);
  if (own && own.text) return "BLOCKED (guard layer 1): " + citation(id) + " - " + what + "\n\nThe rule (" + own.rel + "):\n" + own.text;
  const text = ruleText(root, policy.rules_file || "", id);
  return "BLOCKED (guard layer 1): rule " + id + " - " + what + (text ? "\n\nThe rule (" + policy.rules_file + "):\n" + text : "");
}

// A DOOR reminder for a rule that cannot be forbidden, only recalled at the right moment: the FIRST matching call of a
// session is blocked with the rule; the same call retried passes. Remembered per session in <hooks>/.seen.json (git-ignored,
// last 50 sessions). No session id to remember by => never block (fail-open).
function remindOnce(payload, root, policy, key) {
  const sid = String(payload.session_id || payload.transcript_path || "");
  if (!sid) return false;
  const file = path.join(root, policy.flags_dir || "docs/hooks", ".seen.json");
  let all = {};
  try { all = JSON.parse(fs.readFileSync(file, "utf8")) || {}; } catch { all = {}; }
  const list = Array.isArray(all[sid]) ? all[sid] : [];
  if (list.includes(key)) return false;
  all[sid] = list.concat(key);
  const keys = Object.keys(all);
  for (const k of keys.slice(0, Math.max(0, keys.length - 50))) delete all[k];
  try { fs.writeFileSync(file, JSON.stringify(all)); } catch { return false; }
  return true;
}
const ONCE = "\nThis is a reminder, shown once per session: retry the same call to continue.";

// Paths the language rules do not reach: other people's code, frozen hand-overs, deliberate ASCII samples.
// The write-docx reference samples sit under .claude/skills/ in a repo and under _Store/04_SKILLS/ in the parts store.
// The skill's folder is its old name, its host name (doc-write-docx) or its store name (Skill_Doc_WriteDocx, with the
// assembled host build under Claude/<name>/), and the samples folder is references/ (Agent Skills) or the old reference/.
const LANG_EXEMPT = [/(^|\/)external\//, /(^|\/)attic\//, /(^|\/)(skills|03_SKILLS|04_SKILLS)\/[^/]*(write-docx|WriteDocx)[^/]*\/(Claude\/[^/]+\/)?references?\//];
const CODE_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|py)$/i;

// a rule lives in the folder of its code of law (01_LAW/_Rule/01_Harness/<rule>/)
const SHELF = /^(01_LAW\/_Rule\/\d{2}_[A-Za-z]+|01_LAW\/_Rule|01_LAW\/_Cons|02_STRUCTURE\/_Slot|02_STRUCTURE\/_Host|02_STRUCTURE|03_SKILLS)\/([^\/]+)\/([^\/]+)$/;
const STORE_MARK = "/docs_template/_Store/";
const GATE_KEYS = ["hook", "gate", "prompt", "read", "conform"];
function tokens(s) {
  return String(s).replace(/([a-z])([A-Z])/g, "$1 $2").toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 2 && !/^\d+$/.test(w)
    && !["rule", "cons", "skill", "slot", "struc", "gate", "core", "keys", "the"].includes(w));
}
function parts(store) {
  const out = [];
  for (const shelf of ["01_LAW/_Rule", "01_LAW/_Cons", "02_STRUCTURE/_Slot", "02_STRUCTURE", "03_SKILLS"]) {
    let ents = [];
    try { ents = fs.readdirSync(path.join(store, shelf), { withFileTypes: true }); } catch { continue; }
    const add = (dir, name) => {
      let title = "";
      try { title = (/^#\s+(.*)$/m.exec(fs.readFileSync(path.join(dir, name, name + ".md"), "utf8")) || ["", ""])[1]; } catch {}
      out.push({ name, words: new Set(tokens(name + " " + title)) });
    };
    for (const e of ents) {
      if (!e.isDirectory() || e.name.startsWith("_")) continue;
      if (shelf === "01_LAW/_Rule" && /^\d{2}_[A-Za-z]+$/.test(e.name)) {             // a code of law: its rules
        let inner = [];
        try { inner = fs.readdirSync(path.join(store, shelf, e.name), { withFileTypes: true }); } catch {}
        for (const r of inner) if (r.isDirectory()) add(path.join(store, shelf, e.name), r.name);
        continue;
      }
      add(path.join(store, shelf), e.name);
    }
  }
  return out;
}
// the store a path sits in, read from the ABSOLUTE path (a repo of the workspace writing HS has its own root, not zemory's)
function inStore(root, abs) {
  const norm = path.resolve(root, abs).replace(/\\/g, "/");
  const i = norm.indexOf(STORE_MARK);
  if (i < 0) return null;
  return { store: norm.slice(0, i + STORE_MARK.length - 1), rel: norm.slice(i + STORE_MARK.length), abs: norm };
}
// what a file tool adds (lines not already there, trimmed) and the file as it will be after the call
function change(payload, abs) {
  const tool = payload.tool_name || "";
  const ti = payload.tool_input || {};
  let before = "";
  try { before = fs.readFileSync(abs, "utf8"); } catch { before = ""; }
  let added = "", removed = "", after = before;
  const swap = (text, o, n, all) => (all ? text.split(o).join(n) : text.replace(o, () => n));
  if (tool === "Write") { added = String(ti.content || ""); removed = before; after = added; }
  else if (tool === "Edit") { added = String(ti.new_string || ""); removed = String(ti.old_string || ""); after = swap(before, removed, added, ti.replace_all); }
  else if (tool === "MultiEdit") {
    for (const x of ti.edits || []) {
      added += "\n" + (x.new_string || ""); removed += "\n" + (x.old_string || "");
      after = swap(after, String(x.old_string || ""), String(x.new_string || ""), x.replace_all);
    }
  } else return null;
  const seen = new Map();
  for (const l of removed.split(/\r?\n/)) { const k = l.trim(); if (k) seen.set(k, (seen.get(k) || 0) + 1); }
  const newLines = [];
  for (const l of added.split(/\r?\n/)) {
    const k = l.trim();
    if (!k) continue;
    const n = seen.get(k) || 0;
    if (n > 0) seen.set(k, n - 1); else newLines.push(k);
  }
  return { tool, before, after, newLines };
}
function headerOf(text) { const m = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text || ""); return m ? m[1] : ""; }
function fieldOf(head, key) { const m = new RegExp("^" + key + ":\\s*(.*)$", "m").exec(head); return m ? m[1].trim() : ""; }
function listOf(v) { return String(v || "").replace(/^\[|\]$/g, "").split(/[,·]/).map((x) => x.trim()).filter(Boolean); }
// the version the header file had at the last commit; null when git cannot tell (no repo, a new file) - then not judged
function headVersion(file) {
  try {
    const r = require("node:child_process").spawnSync("git", ["show", "HEAD:./" + path.basename(file)],
      { cwd: path.dirname(file), encoding: "utf8", windowsHide: true, timeout: 5000 });
    if (r.status !== 0) return null;
    const v = Number(fieldOf(headerOf(r.stdout), "version"));
    return Number.isFinite(v) ? v : null;
  } catch { return null; }
}
function implementsOf(text) {
  const lines = String(text || "").split(/\r?\n/);
  const at = lines.findIndex((l) => /^##\s+Implements\b/.test(l));
  if (at < 0) return [];
  const out = [];
  for (const l of lines.slice(at + 1)) {
    if (/^##?\s/.test(l)) break;
    const m = /^-\s*\x60([^\x60]+)\x60/.exec(l);
    if (m) out.push(m[1]);
  }
  return out;
}
function check(payload, root, policy) {
  try {
    const ti = payload.tool_input || {};
    const file = ti.file_path || ti.notebook_path || "";
    if (!file) return null;
    const s = inStore(root, file);
    if (!s) return null;
    const m = SHELF.exec(s.rel);
    if (!m) return null;
    const c = change(payload, s.abs);
    if (!c) return null;
    const partDir = path.join(s.store, m[1], m[2]);
    const all = parts(s.store);
    const known = new Set(all.map((p) => p.name));
    if (!fs.existsSync(partDir)) {
      if (c.tool !== "Write") return null;
      const names = listOf(fieldOf(headerOf(c.after), "checked"));
      if (names.length && names.every((n) => known.has(n))) return null;
      const mine = new Set(tokens(m[2] + " " + c.after.slice(0, 2000)));
      const near = all.map((p) => ({ p: p.name, n: [...p.words].filter((w) => mine.has(w)).length })).filter((x) => x.n > 0)
        .sort((a, b) => b.n - a.n).slice(0, 5).map((x) => x.p);
      const unknown = names.filter((n) => !known.has(n));
      return blocked(root, policy, "02-85", "a NEW part " + m[2] + " is being created. First search the store: the same thing already " +
        "there => add nothing; it fits an existing part => amend that part; only otherwise a new part. Say what was weighed: a header " +
        "line checked: [<existing part>, ...] naming the parts you compared it with (they must exist), and in the text why it does " +
        "not fit them." + (unknown.length ? " Not in the store: " + unknown.join(", ") + "." : "") +
        (near.length ? " Closest now: " + near.join(", ") + "." : ""));
    }
    // an existing part that is given a NEW law: a 🔴 line in its header file, or a new gate key in its gate.json
    const mainFile = path.join(partDir, m[2] + ".md").replace(/\\/g, "/");
    const isMain = s.abs === mainFile;
    const isGate = m[3] === "gate.json";
    let adds = false;
    if (isMain) adds = c.newLines.some((l) => l.includes("\u{1F534}"));
    else if (isGate) adds = GATE_KEYS.some((k) => { const re = new RegExp('"' + k + '"\\s*:'); return re.test(c.after) && !re.test(c.before); });
    if (!adds) return null;
    let mainText = c.after;
    if (!isMain) { try { mainText = fs.readFileSync(mainFile, "utf8"); } catch { mainText = ""; } }
    const head = headerOf(mainText);
    const missing = [];
    const names = listOf(fieldOf(head, "checked")).filter((n) => n !== m[2]);
    const unknown = names.filter((n) => !known.has(n));
    if (!names.length || unknown.length) missing.push("a header line checked: [<laws and skills weighed>] naming existing parts" +
      (unknown.length ? " (not in the store: " + unknown.join(", ") + ")" : ""));
    const hv = headVersion(mainFile);
    const v = Number(fieldOf(head, "version"));
    if (hv !== null && !(v > hv)) missing.push("version above " + hv + " (the last commit)");
    if (m[1] === "03_SKILLS" && fieldOf(head, "frame") !== "true" && !implementsOf(mainText).length)
      missing.push("## Implements naming the law or constitution frame this skill carries out (none holds it => propose it in a law)");
    if (!missing.length) return null;
    return blocked(root, policy, "02-85", "this adds a law to the existing part " + m[2] + " (" + (isGate ? "a new gate in gate.json" :
      "a new \u{1F534} line") + "). First search the store's laws and the skills tied to it: the same thing already there => add " +
      "nothing; a law already holds it => point at that law; otherwise propose it in the law. Then, in the part: " + missing.join(" · ") + ".");
  } catch { return null; }
}
module.exports = { check };
